func ExternalMulti() error {
	x, err := p1.Multi()
	if err != nil {
		return err
	}
	_ = x
	return nil
}

func AssignOp() error {
	err := p1.Foo()
	if err != nil {
		return err
	}
	return nil
}

func ShortIf() error {
	if err := p1.Foo(); err != nil {
		return err
	} else if err2 := p1.Bar(); err2 != nil {
		return err2
	}
	return nil
}

func SwitchInit() error {
	switch err := p1.Foo(); err {
	case nil:
		return nil
	default:
		return err
	}
}

func ForInit() error {
