// compileGlob compiles a glob pattern to regex, mimicking gobwas/glob behavior
// with * matching everything (including /), ? matching single char (including /),
// [...] character classes with ! negation, {a,b} alternation, \ escaping.
// Returns errors matching observed messages for invalid patterns.
func compileGlob(pattern string) (*globMatcher, error) {
	reStr, err := globToRegex(pattern)
	if err != nil {
		return nil, err
	}
	// Anchor full match
	reStr = "^" + reStr + "$"
	re, err := regexp.Compile(reStr)
	if err != nil {
		// Should not happen if our conversion is correct, but return as glob error
		return nil, fmt.Errorf("%v", err)
	}
	return &globMatcher{pattern: pattern, re: re}, nil
}

func (m *globMatcher) Match(s string) bool {
	return m.re.MatchString(s)
}

