	case map[interface{}]interface{}:
		return "map[string]interface {}"
	default:
		return fmt.Sprintf("%T", v)
	}
}

func goValueString(v interface{}) string {
	return fmt.Sprintf("%v", v)
}

func toBool(v interface{}, field string) (bool, decodeError) {
