func analyzeFile(pass *analysis.Pass, file *ast.File, ignoreSigs []string, sigRegexps []*regexp.Regexp, globs []*globMatcher, ifaceRegexps []*regexp.Regexp, reportInternal bool) {
	// Collect all FuncDecl, FuncLit, ReturnStmt
	var funcDecls []*ast.FuncDecl
	var funcLits []*ast.FuncLit
	var returns []*ast.ReturnStmt
	ast.Inspect(file, func(n ast.Node) bool {
		switch x := n.(type) {
		case *ast.FuncDecl:
			funcDecls = append(funcDecls, x)
		case *ast.FuncLit:
			funcLits = append(funcLits, x)
		case *ast.ReturnStmt:
			returns = append(returns, x)
		}
		return true
	})
	for _, ret := range returns {
		handleReturn(pass, ret, funcDecls, funcLits, ignoreSigs, sigRegexps, globs, ifaceRegexps, reportInternal)
	}
	_ = strings.Contains
}

func handleReturn(pass *analysis.Pass, ret *ast.ReturnStmt, funcDecls []*ast.FuncDecl, funcLits []*ast.FuncLit, ignoreSigs []string, sigRegexps []*regexp.Regexp, globs []*globMatcher, ifaceRegexps []*regexp.Regexp, reportInternal bool) {
	if len(ret.Results) == 0 {
		return
	}
	// Determine if inside any FuncLit
	isInsideLit := false
	for _, lit := range funcLits {
		if lit.Pos() <= ret.Pos() && ret.Pos() < lit.End() {
			isInsideLit = true
			break
		}
	}
	// Determine scope for assignment lookup: nearest FuncDecl containing ret, else outermost FuncLit containing ret
	var scope ast.Node
	// Find FuncDecl containing ret (should be at most one, since FuncDecls don't nest)
	for _, fd := range funcDecls {
		if fd.Pos() <= ret.Pos() && ret.Pos() < fd.End() {
			scope = fd
			break
		}
	}
	if scope == nil {
		// No FuncDecl, find outermost FuncLit containing ret (largest range)
		var best *ast.FuncLit
		for _, lit := range funcLits {
			if lit.Pos() <= ret.Pos() && ret.Pos() < lit.End() {
				if best == nil || (lit.Pos() <= best.Pos() && best.End() <= lit.End()) {
					// lit contains best (or best is nil), so lit is outer
					best = lit
				}
			}
		}
		if best != nil {
			scope = best
		} else {
			// Return at file level? Should not happen (returns only inside funcs). Skip.
			return
		}
	}

	for _, expr := range ret.Results {
		if call, ok := expr.(*ast.CallExpr); ok {
			// Direct call: check if error-returning, report if unwrapped, then break
			if !isInsideLit {
				checkDirectCall(pass, call, ignoreSigs, sigRegexps, globs, ifaceRegexps, reportInternal)
			}
			// Always break after first call (even if inside lit or non-error)
			break
		} else if ident, ok := expr.(*ast.Ident); ok {
			// Ident: check if error type
			if !isErrorType(pass.TypesInfo.TypeOf(ident)) {
				continue
			}
			checkIdentReturn(pass, ident, ret, scope, ignoreSigs, sigRegexps, globs, ifaceRegexps, reportInternal)
			// Continue to next
		} else {
			// Other expr: check if error type
			if isErrorType(pass.TypesInfo.TypeOf(expr)) {
				// Error-typed but not call/ident: break, no report
				break
			} else {
				continue
			}
		}
	}
}

func isErrorType(t types.Type) bool {
	if t == nil {
		return false
	}
	// Must be exactly error (universe scope)
	// Check if t is *types.Named with Name=="error" and Pkg()==nil? Or use types.Universe?
	// Simpler: compare to types.Universe.Lookup("error").Type()?
	errObj := types.Universe.Lookup("error")
	if errObj == nil {
		return false
	}
	errType := errObj.Type()
	// Use types.Identical? Or ==? For error interface, identical?
	return types.Identical(t, errType)
}

func checkDirectCall(pass *analysis.Pass, call *ast.CallExpr, ignoreSigs []string, sigRegexps []*regexp.Regexp, globs []*globMatcher, ifaceRegexps []*regexp.Regexp, reportInternal bool) {
	obj, recvType, isMethod := getCalledObject(pass, call)
	if obj == nil {
		return
	}
	// Check if call returns error (any result is error)
	if !funcReturnsError(obj) {
		return
	}
	sig := obj.String()
	// Check ignoreSigs
	for _, s := range ignoreSigs {
		if strings.Contains(sig, s) {
			return
		}
	}
	// Check sig regexps
	for _, re := range sigRegexps {
		if re.MatchString(sig) {
			return
		}
	}
	// Check package globs (callee package)
	if obj.Pkg() != nil {
		pkgPath := obj.Pkg().Path()
		for _, g := range globs {
			if g.Match(pkgPath) {
				return
			}
		}
	}
	// Check interface
	if isMethod && recvType != nil && isInterfaceType(recvType) {
		ifaceStr := types.TypeString(recvType, func(pkg *types.Package) string {
			if pkg == nil {
				return ""
			}
			return pkg.Name()
		})
		matched := false
		for _, re := range ifaceRegexps {
			if re.MatchString(ifaceStr) {
				matched = true
				break
			}
		}
		if !matched {
			// Report as interface
			pass.Report(analysis.Diagnostic{
				Pos:     call.Pos(),
				Message: fmt.Sprintf("error returned from interface method should be wrapped: sig: %s", sig),
			})
			return
		}
		// Else fall through to internal/external
	}
	// Internal vs external
	if isSamePackage(obj, pass.Pkg) {
		if reportInternal {
			pass.Report(analysis.Diagnostic{
				Pos:     call.Pos(),
				Message: fmt.Sprintf("package-internal error should be wrapped: sig: %s", sig),
			})
		}
	} else {
		pass.Report(analysis.Diagnostic{
			Pos:     call.Pos(),
			Message: fmt.Sprintf("error returned from external package is unwrapped: sig: %s", sig),
		})
	}
}

func checkIdentReturn(pass *analysis.Pass, ident *ast.Ident, ret *ast.ReturnStmt, scope ast.Node, ignoreSigs []string, sigRegexps []*regexp.Regexp, globs []*globMatcher, ifaceRegexps []*regexp.Regexp, reportInternal bool) {
	if ident.Name == "_" {
		return
	}
	objUse := pass.TypesInfo.Uses[ident]
	if objUse == nil {
		// Could be Defs? For return ident, should be Uses. If nil, skip.
		return
	}
	// Find last assignment to this object before ret in scope
	call := findLastAssignmentCall(pass, scope, objUse, ret.Pos())
	if call == nil {
		return
	}
	// call is *ast.CallExpr (RHS first, direct)
	calledObj, recvType, isMethod := getCalledObject(pass, call)
	if calledObj == nil {
		return
	}
	// Note: for assignment calls, do NOT check if call returns error (even int calls reported, as observed)
	sig := calledObj.String()
	for _, s := range ignoreSigs {
		if strings.Contains(sig, s) {
			return
		}
	}
	for _, re := range sigRegexps {
		if re.MatchString(sig) {
			return
		}
	}
	if calledObj.Pkg() != nil {
		pkgPath := calledObj.Pkg().Path()
		for _, g := range globs {
			if g.Match(pkgPath) {
				return
			}
		}
	}
	if isMethod && recvType != nil && isInterfaceType(recvType) {
		ifaceStr := types.TypeString(recvType, func(pkg *types.Package) string {
			if pkg == nil {
				return ""
			}
			return pkg.Name()
		})
		matched := false
		for _, re := range ifaceRegexps {
			if re.MatchString(ifaceStr) {
				matched = true
				break
			}
		}
		if !matched {
			pass.Report(analysis.Diagnostic{
				Pos:     ident.Pos(),
				Message: fmt.Sprintf("error returned from interface method should be wrapped: sig: %s", sig),
			})
			return
		}
	}
	if isSamePackage(calledObj, pass.Pkg) {
		if reportInternal {
			pass.Report(analysis.Diagnostic{
				Pos:     ident.Pos(),
				Message: fmt.Sprintf("package-internal error should be wrapped: sig: %s", sig),
			})
		}
	} else {
		pass.Report(analysis.Diagnostic{
			Pos:     ident.Pos(),
			Message: fmt.Sprintf("error returned from external package is unwrapped: sig: %s", sig),
		})
	}
}

func findLastAssignmentCall(pass *analysis.Pass, scope ast.Node, target types.Object, before token.Pos) *ast.CallExpr {
	var bestCall *ast.CallExpr
	var bestPos token.Pos = token.NoPos
	// Traverse scope to find AssignStmt and ValueSpec (var decls)
	ast.Inspect(scope, func(n ast.Node) bool {
		switch x := n.(type) {
		case *ast.AssignStmt:
			// Check if any LHS ident corresponds to target
			matched := false
			for _, lhs := range x.Lhs {
				if ident, ok := lhs.(*ast.Ident); ok {
					if ident.Name == "_" {
						continue
					}
					var obj types.Object
					if o, ok := pass.TypesInfo.Defs[ident]; ok && o != nil {
						obj = o
					} else if o, ok := pass.TypesInfo.Uses[ident]; ok && o != nil {
						obj = o
					} else {
						continue
					}
					if obj == target {
						matched = true
						break
					}
				}
			}
			if !matched {
				return true
			}
			// Check position: assignment must be before return
			// Use statement Pos()? Or LHS Pos()? Use statement Pos().
			if x.Pos() >= before {
				return true
			}
			// Get RHS call (first RHS, direct CallExpr only, not paren)
			var rhs ast.Expr
			if len(x.Rhs) == 0 {
				return true
			} else if len(x.Rhs) == 1 {
				rhs = x.Rhs[0]
			} else {
				rhs = x.Rhs[0] // bug: always first
			}
			call, ok := rhs.(*ast.CallExpr)
			if !ok {
				// Not a call: this assignment overwrites with non-call.
				// Need to consider it as last assignment (with no call) to block earlier calls?
				// E.g., err := Foo(); err = nil; return err => last is nil (non-call), should NOT report.
				// Our current logic picks last CALL assignment, ignoring non-call assignments in between.
				// That's WRONG: we must pick last ASSIGNMENT (whether call or not), and only report if it's a call.
				// So we need to track last assignment position regardless of call, and only report if last is call.
				// How to implement? Keep track of last assignment pos (any), and last call (if last is call)?
				// Simpler: keep bestPos as last assignment pos (any), and bestCall as call if last is call, else nil.
				// For non-call assignment, update bestPos but set bestCall=nil? But what if there are multiple assignments,
				// last is non-call, earlier is call? Then bestCall should be nil (no report). Good.
				// So for non-call, update bestPos and clear bestCall? But need to ensure earlier calls don't override later non-call.
				// Since we iterate in source order? ast.Inspect visits in source order? Yes, it visits nodes in order of appearance?
				// For AssignStmt, Inspect visits in order? Likely yes (preorder, source order). But to be safe, compare positions:
				// If x.Pos() > bestPos, then this is later, update bestPos and bestCall=nil (since non-call).
				if bestPos == token.NoPos || x.Pos() > bestPos {
					bestPos = x.Pos()
					bestCall = nil
				}
				return true
			}
			// Is call
			if bestPos == token.NoPos || x.Pos() > bestPos {
				bestPos = x.Pos()
				bestCall = call
			}
			return true
		case *ast.ValueSpec:
			// var decl: Names, Values
			matched := false
			for _, name := range x.Names {
				if name.Name == "_" {
					continue
				}
				if o, ok := pass.TypesInfo.Defs[name]; ok && o != nil && o == target {
					matched = true
					break
				}
			}
			if !matched {
				return true
			}
			if x.Pos() >= before {
				return true
			}
			if len(x.Values) == 0 {
				// var err error (no value): treat as non-call assignment (blocks earlier? No, earlier can't exist before var decl?
				// Since var decl defines the object, any assignment before it would be to different object? Actually for `var err error; err = Foo()`,
				// the var decl (no value) is before `err = Foo()`, so last is `err = Foo()` (call), reported. Good.
				// For `var err error; return err` (no assignment), last is var decl (non-call), not reported. Good.
				// So update bestPos with nil call.
				if bestPos == token.NoPos || x.Pos() > bestPos {
					bestPos = x.Pos()
					bestCall = nil
				}
				return true
			}
			var rhs ast.Expr
			if len(x.Values) == 1 {
				rhs = x.Values[0]
			} else {
				rhs = x.Values[0] // bug: always first
			}
			call, ok := rhs.(*ast.CallExpr)
			if !ok {
				if bestPos == token.NoPos || x.Pos() > bestPos {
					bestPos = x.Pos()
					bestCall = nil
				}
				return true
			}
			if bestPos == token.NoPos || x.Pos() > bestPos {
				bestPos = x.Pos()
				bestCall = call
			}
			return true
		}
		return true
	})
	return bestCall
}

func getCalledObject(pass *analysis.Pass, call *ast.CallExpr) (types.Object, types.Type, bool) {
	// Returns obj, recvType, isMethod
	switch fun := call.Fun.(type) {
	case *ast.Ident:
		obj := pass.TypesInfo.Uses[fun]
		if obj == nil {
			return nil, nil, false
		}
		// Check if builtin? Builtins have no Pkg? Actually *types.Builtin has no signature? Skip builtins.
		if _, ok := obj.(*types.Builtin); ok {
			return nil, nil, false
		}
		if _, ok := obj.(*types.TypeName); ok {
			// Conversion, not call
			return nil, nil, false
		}
		return obj, nil, false
	case *ast.SelectorExpr:
		// Check Selections first (methods/fields)
		if sel, ok := pass.TypesInfo.Selections[fun]; ok && sel != nil {
			obj := sel.Obj()
			if obj == nil {
				return nil, nil, false
			}
			// Could be Func (method) or Var (field)
			recv := sel.Recv()
			// isMethod? For methods, Obj is *types.Func with receiver? For fields, Obj is *types.Var with IsField?
			// For interface check, only methods on interfaces matter, not fields.
			// How to distinguish? If Obj is *types.Func, it's a method (could be on struct or interface).
			// If Obj is *types.Var (field), it's a field func value, not a method, so not interface.
			if _, ok := obj.(*types.Func); ok {
				return obj, recv, true
			}
			// Field
			return obj, nil, false
		}
		// No selection, must be qualified identifier (package.Func/Var)
		obj := pass.TypesInfo.Uses[fun.Sel]
		if obj == nil {
			return nil, nil, false
		}
		if _, ok := obj.(*types.Builtin); ok {
			return nil, nil, false
		}
		if _, ok := obj.(*types.TypeName); ok {
			return nil, nil, false
		}
		return obj, nil, false
	default:
		// IndexExpr (generic explicit), ParenExpr, FuncLit, etc.: skip (as observed, not reported)
		return nil, nil, false
	}
}

func funcReturnsError(obj types.Object) bool {
	var sig *types.Signature
	switch o := obj.(type) {
	case *types.Func:
		t, ok := o.Type().(*types.Signature)
		if !ok {
			return false
		}
		sig = t
	case *types.Var:
		// Could be func var or field
		t, ok := o.Type().(*types.Signature)
		if !ok {
			return false
		}
		sig = t
	default:
		return false
	}
	if sig == nil {
		return false
	}
	results := sig.Results()
	if results == nil {
		return false
	}
	for i := 0; i < results.Len(); i++ {
		if isErrorType(results.At(i).Type()) {
			return true
		}
	}
	return false
}

func isInterfaceType(t types.Type) bool {
	if t == nil {
		return false
	}
	// Dereference pointer? Interfaces are never pointers, but just in case, if *interface? Unlikely. Don't deref.
	// Check if underlying is *types.Interface
	// For *types.Named (named interface like p1.Store), Underlying() is *types.Interface
	// For *types.Interface (anonymous), itself is interface
	if iface, ok := t.Underlying().(*types.Interface); ok {
		_ = iface
		return true
	}
	return false
}

func isSamePackage(obj types.Object, caller *types.Package) bool {
	if obj == nil || caller == nil {
		return true // treat as same? For safety, if unknown, treat as internal (not reported by default)
	}
	pkg := obj.Pkg()
	if pkg == nil {
		// Local var, field? For fields, Pkg() is package where struct defined, not nil. For locals, nil => same package (internal)
		return true
	}
	return pkg.Path() == caller.Path()
}
