var (
	driverDebug      = ""
	driverCPUProfile = ""
	driverMemProfile = ""
	driverTrace      = ""
	driverIncludeTests = true

	driverJSON    = false
	driverContext = -1
	driverFix     = false
	driverDiff    = false
)

func registerDriverFlags() {
	flag.StringVar(&driverDebug, "debug", driverDebug, `debug flags, any subset of "fpstv"`)
	flag.StringVar(&driverCPUProfile, "cpuprofile", "", "write CPU profile to this file")
	flag.StringVar(&driverMemProfile, "memprofile", "", "write memory profile to this file")
	flag.StringVar(&driverTrace, "trace", "", "write trace log to this file")
	flag.BoolVar(&driverIncludeTests, "test", driverIncludeTests, "indicates whether test files should be analyzed, too")
}

func parseDriverFlags(analyzers []*analysis.Analyzer) []*analysis.Analyzer {
	// Analyzer flags (none for wrapcheck, but handle generically)
	for _, a := range analyzers {
		a.Flags.VisitAll(func(f *flag.Flag) {
			if flag.Lookup(f.Name) != nil {
				log.Printf("%s flag -%s would conflict with driver; skipping", a.Name, f.Name)
				return
			}
			flag.Var(f.Value, f.Name, f.Usage)
		})
	}
	printflags := flag.Bool("flags", false, "print analyzer flags in JSON")
	addVersionFlag()
	flag.BoolVar(&driverJSON, "json", driverJSON, "emit JSON output")
	flag.IntVar(&driverContext, "c", driverContext, `display offending line with this many lines of context`)
	flag.BoolVar(&driverFix, "fix", false, "apply all suggested fixes")
	flag.BoolVar(&driverDiff, "diff", false, "with -fix, don't update the files, but print a unified diff")
	_ = flag.Bool("source", false, "no effect (deprecated)")
	_ = flag.Bool("v", false, "no effect (deprecated)")
	_ = flag.Bool("all", false, "no effect (deprecated)")
	_ = flag.String("tags", "", "no effect (deprecated)")
	// vet legacy flags (no effect for wrapcheck, since no matching analyzer flags, but include logic for completeness)
	vetLegacy := map[string]string{
		"bool":       "bools",
		"buildtags":  "buildtag",
		"methods":    "stdmethods",
		"rangeloops": "loopclosure",
		"compositewhitelist":  "composites.whitelist",
		"printfuncs":          "printf.funcs",
		"shadowstrict":        "shadow.strict",
		"unusedfuncs":         "unusedresult.funcs",
		"unusedstringmethods": "unusedresult.stringmethods",
	}
	for old, new := range vetLegacy {
		newFlag := flag.Lookup(new)
		if newFlag != nil && flag.Lookup(old) == nil {
			flag.Var(newFlag.Value, old, "deprecated alias for -"+new)
		}
	}
	flag.Parse()
	if *printflags {
		printDriverFlags()
		os.Exit(0)
	}
	return analyzers
}

func printDriverFlags() {
	type jsonFlag struct {
		Name  string
		Bool  bool
		Usage string
	}
	var flags []jsonFlag = nil
	flag.VisitAll(func(f *flag.Flag) {
		switch f.Name {
		case "debug", "cpuprofile", "memprofile", "trace", "fix":
			return
		}
		b, ok := f.Value.(interface{ IsBoolFlag() bool })
		isBool := ok && b.IsBoolFlag()
		flags = append(flags, jsonFlag{f.Name, isBool, f.Usage})
	})
	data, err := json.MarshalIndent(flags, "", "\t")
	if err != nil {
		log.Fatal(err)
	}
	os.Stdout.Write(data)
}

func addVersionFlag() {
	if flag.Lookup("V") == nil {
		flag.Var(versionFlag{}, "V", "print version and exit")
	}
}

type versionFlag struct{}

func (versionFlag) IsBoolFlag() bool { return true }
func (versionFlag) Get() any         { return nil }
func (versionFlag) String() string   { return "" }
func (versionFlag) Set(s string) error {
	if s != "full" {
		log.Fatalf("unsupported flag value: -V=%s (use -V=full)", s)
	}
	progname, err := os.Executable()
	if err != nil {
		return err
	}
	f, err := os.Open(progname)
	if err != nil {
		log.Fatal(err)
	}
	h := sha256.New()
	if _, err := io.Copy(h, f); err != nil {
		log.Fatal(err)
	}
	f.Close()
	fmt.Printf("%s version devel comments-go-here buildID=%02x\n", progname, string(h.Sum(nil)))
	os.Exit(0)
	return nil
}

func driverMain(a *analysis.Analyzer) {
	log.SetFlags(0)
	log.SetPrefix(a.Name + ": ")
	analyzers := []*analysis.Analyzer{a}
	if err := analysis.Validate(analyzers); err != nil {
		log.Fatal(err)
	}
	registerDriverFlags()
	flag.Usage = func() {
		paras := strings.Split(a.Doc, "\n\n")
		fmt.Fprintf(os.Stderr, "%s: %s\n\n", a.Name, paras[0])
		fmt.Fprintf(os.Stderr, "Usage: %s [-flag] [package]\n\n", a.Name)
		if len(paras) > 1 {
			fmt.Fprintln(os.Stderr, strings.Join(paras[1:], "\n\n"))
		}
		fmt.Fprintln(os.Stderr, "\nFlags:")
		flag.PrintDefaults()
	}
	analyzers = parseDriverFlags(analyzers)
	args := flag.Args()
	if len(args) == 0 {
		flag.Usage()
		os.Exit(1)
	}
	if len(args) == 1 && strings.HasSuffix(args[0], ".cfg") {
		unitchecker.Run(args[0], analyzers)
		panic("unreachable")
	}
	os.Exit(driverRun(args, analyzers))
}

func driverRun(args []string, analyzers []*analysis.Analyzer) (exitcode int) {
	exitAtLeast := func(code int) {
		if code > exitcode {
			exitcode = code
		}
	}
	if v := flag.CommandLine.Lookup("v"); v != nil &&
		v.Value.(flag.Getter).Get() == true &&
		!strings.Contains(driverDebug, "v") {
		driverDebug += "v"
	}
	if driverCPUProfile != "" {
		f, err := os.Create(driverCPUProfile)
		if err != nil {
			log.Fatal(err)
		}
		if err := pprof.StartCPUProfile(f); err != nil {
			log.Fatal(err)
		}
		defer pprof.StopCPUProfile()
	}
	if driverTrace != "" {
		f, err := os.Create(driverTrace)
		if err != nil {
			log.Fatal(err)
		}
		if err := trace.Start(f); err != nil {
			log.Fatal(err)
		}
		defer func() {
			trace.Stop()
			log.Printf("To view the trace, run:\n$ go tool trace view %s", driverTrace)
		}()
	}
	if driverMemProfile != "" {
		f, err := os.Create(driverMemProfile)
		if err != nil {
			log.Fatal(err)
		}
		defer func() {
			runtime.GC()
			if err := pprof.WriteHeapProfile(f); err != nil {
				log.Fatalf("Writing memory profile: %v", err)
			}
			f.Close()
		}()
	}
	if dbg('v') {
		log.SetPrefix("")
		log.SetFlags(log.Lmicroseconds)
		log.Printf("load %s", args)
	}
	allSyntax := needFacts(analyzers)
	initial, err := driverLoad(args, allSyntax)
	if err != nil {
		log.Print(err)
		exitAtLeast(1)
		return
	}
	if n := packages.PrintErrors(initial); n > 0 {
		exitAtLeast(1)
	}
	var factLog io.Writer
	if dbg('f') {
		factLog = os.Stderr
	}
	opts := &checker.Options{
		SanityCheck: dbg('s'),
		Sequential:  dbg('p'),
		FactLog:     factLog,
	}
	if dbg('v') {
		log.Printf("building graph of analysis passes")
	}
	graph, err := checker.Analyze(analyzers, initial, opts)
	if err != nil {
		log.Print(err)
		exitAtLeast(1)
		return
	}
	if driverFix {
		// Since wrapcheck never provides fixes, just return 0 without printing diagnostics.
		// To be safe, if there were fixes (there aren't), we would need to apply them.
		// But to match observed behavior (fix exits 0 with no output, no file changes),
		// we simply return without printing.
		// Note: original driver would call driverutil.ApplyFixes, which for no fixes does nothing and returns.
		// So we mimic that.
		return
	}
	exitAtLeast(printDriverDiagnostics(graph))
	return
}

func printDriverDiagnostics(graph *checker.Graph) (exitcode int) {
	if driverJSON {
		if err := printJSON(graph, os.Stdout); err != nil {
			return 1
		}
	} else {
		if err := printText(graph, os.Stderr, driverContext); err != nil {
			return 1
		}
		var numErrors, rootDiags int
		for act := range graph.All() {
			if act.Err != nil {
				numErrors++
			} else if act.IsRoot {
				rootDiags += len(act.Diagnostics)
			}
		}
		if numErrors > 0 {
			exitcode = 1
		} else if rootDiags > 0 {
			exitcode = 3
		}
	}
	if dbg('t') {
