func printText(graph *checker.Graph, w io.Writer, contextLines int) error {
	type key struct {
		pos token.Position
		*analysis.Analyzer
		message string
	}
	seen := make(map[key]bool)
	buf := new(bytes.Buffer)
	forEachRoot(graph, func(act *checker.Action) error {
		if act.Err != nil {
			fmt.Fprintf(w, "%s: %v\n", act.Analyzer.Name, act.Err)
		} else if act.IsRoot {
			for _, diag := range act.Diagnostics {
				posn := act.Package.Fset.Position(diag.Pos)
				k := key{posn, act.Analyzer, diag.Message}
				if seen[k] {
					continue
				}
				seen[k] = true
				printPlain(buf, act.Package.Fset, contextLines, diag)
			}
		}
		return nil
	})
	_, err := w.Write(buf.Bytes())
	return err
}

func printPlain(out io.Writer, fset *token.FileSet, contextLines int, diag analysis.Diagnostic) {
	print := func(pos, end token.Pos, message string) {
		posn := fset.Position(pos)
		fmt.Fprintf(out, "%s: %s\n", posn, message)
		if contextLines >= 0 {
			endPos := fset.Position(end)
			if !endPos.IsValid() {
				endPos = posn
			}
			data, _ := os.ReadFile(posn.Filename)
			lines := strings.Split(string(data), "\n")
			for i := posn.Line - contextLines; i <= endPos.Line+contextLines; i++ {
				if 1 <= i && i <= len(lines) {
					fmt.Fprintf(out, "%d\t%s\n", i, lines[i-1])
				}
			}
		}
	}
	print(diag.Pos, diag.End, diag.Message)
	for _, rel := range diag.Related {
		print(rel.Pos, rel.End, "\t"+rel.Message)
	}
}

