	driverCPUProfile = ""
	driverMemProfile = ""
	driverTrace      = ""
	driverIncludeTests = true

	driverJSON    = false
	driverContext = -1
	driverFix     = false
	driverDiff    = false
)

func registerDriverFlags() {
	flag.StringVar(&driverDebug, "debug", driverDebug, `debug flags, any subset of "fpstv"`)
	flag.StringVar(&driverCPUProfile, "cpuprofile", "", "write CPU profile to this file")
	flag.StringVar(&driverMemProfile, "memprofile", "", "write memory profile to this file")
	flag.StringVar(&driverTrace, "trace", "", "write trace log to this file")
	flag.BoolVar(&driverIncludeTests, "test", driverIncludeTests, "indicates whether test files should be analyzed, too")
}

func parseDriverFlags(analyzers []*analysis.Analyzer) []*analysis.Analyzer {
	// Analyzer flags (none for wrapcheck, but handle generically)
	for _, a := range analyzers {
		a.Flags.VisitAll(func(f *flag.Flag) {
			if flag.Lookup(f.Name) != nil {
				log.Printf("%s flag -%s would conflict with driver; skipping", a.Name, f.Name)
				return
			}
			flag.Var(f.Value, f.Name, f.Usage)
		})
	}
	printflags := flag.Bool("flags", false, "print analyzer flags in JSON")
	addVersionFlag()
	flag.BoolVar(&driverJSON, "json", driverJSON, "emit JSON output")
	flag.IntVar(&driverContext, "c", driverContext, `display offending line with this many lines of context`)
	flag.BoolVar(&driverFix, "fix", false, "apply all suggested fixes")
	flag.BoolVar(&driverDiff, "diff", false, "with -fix, don't update the files, but print a unified diff")
	_ = flag.Bool("source", false, "no effect (deprecated)")
	_ = flag.Bool("v", false, "no effect (deprecated)")
	_ = flag.Bool("all", false, "no effect (deprecated)")
	_ = flag.String("tags", "", "no effect (deprecated)")
	// vet legacy flags (no effect for wrapcheck, since no matching analyzer flags, but include logic for completeness)
	vetLegacy := map[string]string{
		"bool":       "bools",
		"buildtags":  "buildtag",
		"methods":    "stdmethods",
		"rangeloops": "loopclosure",
		"compositewhitelist":  "composites.whitelist",
		"printfuncs":          "printf.funcs",
		"shadowstrict":        "shadow.strict",
		"unusedfuncs":         "unusedresult.funcs",
		"unusedstringmethods": "unusedresult.stringmethods",
	}
	for old, new := range vetLegacy {
		newFlag := flag.Lookup(new)
		if newFlag != nil && flag.Lookup(old) == nil {
			flag.Var(newFlag.Value, old, "deprecated alias for -"+new)
		}
	}
	flag.Parse()
	if *printflags {
		printDriverFlags()
		os.Exit(0)
	}
	return analyzers
}

func printDriverFlags() {
	type jsonFlag struct {
		Name  string
		Bool  bool
		Usage string
	}
	var flags []jsonFlag = nil
	flag.VisitAll(func(f *flag.Flag) {
		switch f.Name {
		case "debug", "cpuprofile", "memprofile", "trace", "fix":
			return
		}
		b, ok := f.Value.(interface{ IsBoolFlag() bool })
		isBool := ok && b.IsBoolFlag()
		flags = append(flags, jsonFlag{f.Name, isBool, f.Usage})
	})
	data, err := json.MarshalIndent(flags, "", "\t")
	if err != nil {
		log.Fatal(err)
	}
	os.Stdout.Write(data)
}

func addVersionFlag() {
	if flag.Lookup("V") == nil {
		flag.Var(versionFlag{}, "V", "print version and exit")
	}
